// Experimental CLI preloader only. Never loaded by the application.
const root = '<performance-backend-root>';
const source = process.argv.find(arg => arg.startsWith('--source-root='))?.slice('--source-root='.length);
if (process.argv.some(arg => arg.startsWith('--mode=')) && source === root) {
  const { default: database } = await import(root + '/src/lib/prisma.js');
  const findImport = database.pontoImport.findUnique;
  const findProjects = database.project.findMany;
  let packet = null;
  const hydrate = (rows, fields) => rows.map(row => ({ ...row, ...Object.fromEntries(fields.filter(key => row[key] != null)
    .map(key => [key, new Date(row[key].length === 10 ? row[key] + 'T00:00:00.000Z' : /(?:Z|[+-]\d\d:\d\d)$/.test(row[key]) ? row[key] : row[key] + 'Z')])) }));
  database.pontoImport.findUnique = async args => {
    packet = null;
    const selected = await findImport.apply(database.pontoImport, [args]);
    if (!selected) return selected;
    const projects = await findProjects.call(database.project, { select: {
      id: true, code: true, offshore: true, laborSleepModeByCollaborator: true, laborCollaboratorIds: true,
      operatorId: true, mobilizationDate: true, demobilizationDate: true, deletedAt: true
    } });
    const ids = projects.map(project => project.id), imports = [selected.id];
    const start = selected.periodStart, end = selected.periodEnd;
    const exclusive = new Date(new Date(end).getTime() + 86400000);
    const [row] = await database.$queryRaw`
      SELECT jsonb_build_object(
        'roles', (SELECT COALESCE(jsonb_agg(jsonb_build_object('id', r.id, 'name', r.name)), '[]'::jsonb) FROM "JobRole" r),
        'profiles', (SELECT COALESCE(jsonb_agg(jsonb_build_object('key', p.key, 'jobRoleId', p."jobRoleId",
          'parameterSets', (SELECT COALESCE(jsonb_agg(jsonb_build_object('version', s.version, 'effectiveDate', s."effectiveDate",
            'createdAt', s."createdAt", 'params', s.params)), '[]'::jsonb) FROM "CostParameterSet" s WHERE s."costProfileId" = p.id))), '[]'::jsonb) FROM "CostProfile" p),
        'settings', (SELECT COALESCE(jsonb_agg(jsonb_build_object('key', s.key, 'numberValue', s."numberValue")), '[]'::jsonb)
          FROM "AcompanhamentoSetting" s WHERE s.key IN ('epiAnnualCost', 'examsTrainingAnnualCost', 'offshoreExamsTrainingAnnualCost')),
        'aliases', (SELECT COALESCE(jsonb_agg(jsonb_build_object('normalizedTag', a."normalizedTag", 'projectId', a."projectId")), '[]'::jsonb)
          FROM "PontoProjectTagAlias" a WHERE a."projectId" = ANY(${ids}::text[])),
        'overrides', (SELECT COALESCE(jsonb_agg(jsonb_build_object('collaboratorId', o."collaboratorId", 'workDate', o."workDate", 'projectId', o."projectId")), '[]'::jsonb)
          FROM "PontoDayProjectOverride" o WHERE o."workDate" >= ${start} AND o."workDate" < ${exclusive} AND o."projectId" = ANY(${ids}::text[])),
        'absences', (SELECT COALESCE(jsonb_agg(to_jsonb(a)), '[]'::jsonb) FROM "CollaboratorAbsence" a WHERE a."deletedAt" IS NULL
          AND a."startDate" <= ${end} AND a."endDate" >= ${start} AND a."collaboratorId" IN (
            SELECT DISTINCT p."collaboratorId" FROM "PontoPeriodSummary" p WHERE p."importId" = ANY(${imports}::text[]) AND p."collaboratorId" IS NOT NULL)),
        'holidays', (SELECT COALESCE(jsonb_agg(to_jsonb(h) ORDER BY h."holidayDate"), '[]'::jsonb) FROM "WorkforceHoliday" h
          WHERE h."deletedAt" IS NULL AND h."holidayDate" >= ${start} AND h."holidayDate" <= ${end}),
        'state', (SELECT to_jsonb(s) FROM "WorkforceCalendarState" s WHERE s.id = 'global')
      ) AS data
    `;
    packet = { ...row.data, projects };
    packet.profiles = packet.profiles.map(profile => ({ ...profile, parameterSets: hydrate(profile.parameterSets, ['effectiveDate', 'createdAt']) }));
    packet.overrides = hydrate(packet.overrides, ['workDate']);
    packet.absences = hydrate(packet.absences, ['startDate', 'endDate']);
    packet.holidays = hydrate(packet.holidays, ['holidayDate']);
    return selected;
  };
  const replace = (model, method, read) => {
    const original = database[model][method];
    database[model][method] = function (...args) { return packet ? Promise.resolve(read(packet, args[0])) : original.apply(this, args); };
  };
  replace('project', 'findMany', data => data.projects);
  replace('jobRole', 'findMany', data => data.roles);
  replace('costProfile', 'findMany', data => data.profiles);
  replace('acompanhamentoSetting', 'findMany', data => data.settings);
  replace('pontoProjectTagAlias', 'findMany', data => data.aliases);
  replace('pontoDayProjectOverride', 'findMany', data => data.overrides);
  replace('collaboratorAbsence', 'findMany', (data, args) => data.absences.filter(row => args.where.collaboratorId.in.includes(row.collaboratorId)));
  replace('workforceHoliday', 'findMany', data => data.holidays);
  replace('workforceCalendarState', 'findUnique', data => data.state);
}

