        'absences', (SELECT COALESCE(jsonb_agg(to_jsonb(a)), '[]'::jsonb) FROM "CollaboratorAbsence" a WHERE a."deletedAt" IS NULL
          AND a."startDate" <= ${end} AND a."endDate" >= ${start} AND a."collaboratorId" IN (
            SELECT DISTINCT p."collaboratorId" FROM "PontoPeriodSummary" p WHERE p."importId" = ANY(${imports}::text[]) AND p."collaboratorId" IS NOT NULL)),
