  replace('costProfile', 'findMany', data => data.profiles);
  replace('acompanhamentoSetting', 'findMany', data => data.settings);
  replace('pontoProjectTagAlias', 'findMany', data => data.aliases);
  replace('pontoDayProjectOverride', 'findMany', data => data.overrides);
  replace('collaboratorAbsence', 'findMany', (data, args) => data.absences.filter(row => args.where.collaboratorId.in.includes(row.collaboratorId)));
